def _compute_policy_entropy_err(self, pi, a):
    """Compute policy error and entropy error for a batch.

    Pass in ``min_prob`` to avoid ``Nan`` in logrithms.

    Returns:
        dict of
        ``logpi``: log policy
        ``policy_err``: polict error
        ``entropy_err``: entropy error
    """
    errs = {}
    if isinstance(pi, list):
        # Action map, and we need compute the error one by one.
        for i, pix in enumerate(pi):
            for j, pixy in enumerate(pix):
                errs = accumulate(
                    errs,
                    self._compute_one_policy_entropy_err(
                        pixy, a[:, i, j], self.options.min_prob)
                )
    else:
        errs = self._compute_one_policy_entropy_err(pi, a)

    return errs

def find_package_data(pkgdir):
    """ Just include all files that won't be included as package modules.
    """
    files = []
    for root, dirnames, filenames in os.walk(pkgdir):
        not_a_package = '__init__.py' not in filenames
        for fn in filenames:
            basename, fext = os.path.splitext(fn)
            if not_a_package or (fext not in PYEXT) or ('static' in fn):
                files.append(relpath(join(root, fn), pkgdir))
    return files

