def __call__(self, doc):
    """Clean the document."""
    if hasattr(doc, 'getroot'):
        doc = doc.getroot()

    if self.fix_whitespace:
        # Ensure newlines around block elements
        for el in doc.iterdescendants():
            if el.tag in BLOCK_ELEMENTS:
                el.tail = (el.tail or '') + '\n'
                previous = el.getprevious()
                parent = el.getparent()
                if previous is None:
                    parent.text = (parent.text or '') + '\n'
                else:
                    previous.tail = (previous.tail or '') + '\n'

    # Remove elements that match kill_xpath
    if self.kill_xpath:
        for el in doc.xpath(self.kill_xpath, namespaces=self.namespaces):
            #log.debug('Killing: %s' % tostring(el))
            parent = el.getparent()
            # We can't kill the root element!
            if parent is None:
                continue
            if el.tail:
                previous = el.getprevious()
                if previous is None:
                    parent.text = (parent.text or '') + el.tail
                else:
                    previous.tail = (previous.tail or '') + el.tail
            parent.remove(el)

    # Collect all the allowed elements
    to_keep = [el for el in doc.xpath(self.allow_xpath, namespaces=self.namespaces)] if self.allow_xpath else []

    # Replace elements that match strip_xpath with their contents
    if self.strip_xpath:
        for el in doc.xpath(self.strip_xpath, namespaces=self.namespaces):
            # Skip if allowed by allow_xpath
            if el in to_keep:
                continue
            parent = el.getparent()
            previous = el.getprevious()
            # We can't strip the root element!
            if parent is None:
                continue
            # Append the text to previous tail (or parent text if no previous), ensuring newline if block level
            if el.text and isinstance(el.tag, six.string_types):
                if previous is None:
                    parent.text = (parent.text or '') + el.text
                else:
                    previous.tail = (previous.tail or '') + el.text
            # Append the tail to last child tail, or previous tail, or parent text, ensuring newline if block level
            if el.tail:
                if len(el):
                    last = el[-1]
                    last.tail = (last.tail or '') + el.tail
                elif previous is None:
                    parent.text = (parent.text or '') + el.tail
                else:
                    previous.tail = (previous.tail or '') + el.tail
            index = parent.index(el)
            parent[index:index+1] = el[:]

    # Collapse whitespace down to a single space or a single newline
    if self.fix_whitespace:
        for el in doc.iter():
            if el.text is not None:
                el.text = re.sub(r'\s*\n\s*', '\n', el.text)
                el.text = re.sub(r'[ \t]+', ' ', el.text)
                # el.text = re.sub(r'\s+', ' ', el.text)
            if el.tail is not None:
                el.tail = re.sub(r'\s*\n\s*', '\n', el.tail)
                el.tail = re.sub(r'[ \t]+', ' ', el.tail)

def clean_html(self, html):
    """Apply ``Cleaner`` to HTML string or document and return a cleaned string or document."""
    result_type = type(html)
    if isinstance(html, six.string_types):
        doc = html_fromstring(html)
    else:
        doc = copy.deepcopy(html)
    self(doc)
    if issubclass(result_type, six.binary_type):
        return tostring(doc, encoding='utf-8')
    elif issubclass(result_type, six.text_type):
        return tostring(doc, encoding='unicode')
    else:
        return doc

def clean_markup(self, markup, parser=None):
    """Apply ``Cleaner`` to markup string or document and return a cleaned string or document."""
    result_type = type(markup)
    if isinstance(markup, six.string_types):
        doc = fromstring(markup, parser=parser)
    else:
        doc = copy.deepcopy(markup)
    self(doc)
    if issubclass(result_type, six.binary_type):
        return tostring(doc, encoding='utf-8')
    elif issubclass(result_type, six.text_type):
        return tostring(doc, encoding='unicode')
    else:
        return doc

def str2size(s, scale=1024):
    """Convert size-string.

    String format: <value>[:space:]<B | K | M | ...> to bytes.

    :param s: size-string
    :param scale: base size
    """
    if not s:
        return 0

    if isinstance(s, six.integer_types):
        return s

    match = re.match(r'^([\.\d]+)\s*([BbKkMmGgTtPpEeZzYy]?)', s)
    if match is None:
        raise ValueError(_('Invalid value: %(value)s')
                         % {'value': s})

    groups = match.groups()
    value = float(groups[0])
    suffix = groups[1].upper() if groups[1] else 'B'

    types = ('B', 'K', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y')
    for i, t in enumerate(types):
        if suffix == t:
            return int(value * pow(scale, i))

def get_rrmgr_cmd(src, dst, compression=None, tcp_buf_size=None,
                  connections=None):
    """Returns rrmgr command for source and destination."""
    cmd = ['rrmgr', '-s', 'zfs']
    if compression:
        cmd.extend(['-c', six.text_type(compression)])
    cmd.append('-q')
    cmd.append('-e')
    if tcp_buf_size:
        cmd.extend(['-w', six.text_type(tcp_buf_size)])
    if connections:
        cmd.extend(['-n', six.text_type(connections)])
    cmd.extend([src, dst])
    return ' '.join(cmd)

def parse_nms_url(url):
    """Parse NMS url into normalized parts like scheme, user, host and others.

    Example NMS URL:
        auto://admin:nexenta@192.168.1.1:2000/

    NMS URL parts:

    .. code-block:: none

        auto                True if url starts with auto://, protocol
                            will be automatically switched to https
                            if http not supported;
        scheme (auto)       connection protocol (http or https);
        user (admin)        NMS user;
        password (nexenta)  NMS password;
        host (192.168.1.1)  NMS host;
        port (2000)         NMS port.

    :param url: url string
    :return: tuple (auto, scheme, user, password, host, port, path)
    """
    pr = urlparse.urlparse(url)
    scheme = pr.scheme
    auto = scheme == 'auto'
    if auto:
        scheme = 'http'
    user = 'admin'
    password = 'nexenta'
    if '@' not in pr.netloc:
        host_and_port = pr.netloc
    else:
        user_and_password, host_and_port = pr.netloc.split('@', 1)
        if ':' in user_and_password:
            user, password = user_and_password.split(':')
        else:
            user = user_and_password
    if ':' in host_and_port:
        host, port = host_and_port.split(':', 1)
    else:
        host, port = host_and_port, '2000'
    return auto, scheme, user, password, host, port, '/rest/nms/'

